class Animal {
  void sound() {
    System.out.println("Animal sound");
  }
}
class Dog extends Animal {
  void sound() {
    ___.sound();
    System.out.println("Dog sound");
  }
}
public class Main{
  public static void main(String args[]){
    Dog d = new Dog();
    d.sound();
  }
}

