int main(){
    int arr[5] = {1,2,3,4,5};
    int *left = arr;
    int *right = arr + 4;
    while (left < right) {
        int temp = *left;
        *left = *right;
        *right = temp;
        left++;
        right--;
    }
    for (int i = 0; i < 5; i++) {
        printf("%d ", arr[i]);
    }
}

public class Main {
    public static void main(String[] args) {
        int[][] arr = {{1,2,3},{4,5},{6,7,8,9}};
        int total = 0;
        for (int i = 0; i < arr.length; i++) {
            int rowSum = 0;
            for (int j = 0; j < arr[i].length; j++) {
                rowSum += arr[i][j];
            }
            System.out.println(rowSum);
            total += rowSum;
        }
        System.out.println(total);
    }
}
